# ============================================================
# 1. HELPER FUNCTIONS
# ============================================================

def normalize_colname(x):

    return re.sub(
        r"[\s_\-\(\)\[\]/\\.]+",
        "",
        str(x)
    ).lower()



def find_column(columns, candidates):

    norm_map = {
        normalize_colname(c): c
        for c in columns
    }

    # exact
    for candidate in candidates:

        c = normalize_colname(candidate)

        if c in norm_map:
            return norm_map[c]


    # partial
    for candidate in candidates:

        c = normalize_colname(candidate)

        for norm_col, original in norm_map.items():

            if c in norm_col:
                return original

    return None



def normalize_station_id(series):

    s = (
        series.astype(str)
        .str.strip()
    )

    # 1001 / 1001.0 / ST-1001 대응
    extracted = s.str.extract(
        r"(\d+)",
        expand=False
    )

    return pd.to_numeric(
        extracted,
        errors="coerce"
    ).astype("Int64")



def numeric_clean(series):

    return pd.to_numeric(

        series.astype(str)
        .str.replace(",", "", regex=False)
        .str.strip(),

        errors="coerce"
    )



def parse_date(series):

    s = (
        series.astype(str)
        .str.strip()
        .str.replace(
            r"\.0$",
            "",
            regex=True
        )
    )


    # YYYYMMDD
    dt = pd.to_datetime(
        s,
        format="%Y%m%d",
        errors="coerce"
    )


    missing = dt.isna()


    if missing.any():

        dt.loc[missing] = pd.to_datetime(
            s.loc[missing],
            errors="coerce"
        )


    return dt.dt.normalize()



def parse_hour(series):

    s = (
        series.astype(str)
        .str.strip()
    )


    num = pd.to_numeric(
        s,
        errors="coerce"
    )


    hour = pd.Series(
        np.nan,
        index=series.index,
        dtype=float
    )


    # 0 ~ 23
    mask = (
        num.notna()
        & (num >= 0)
        & (num <= 23)
    )

    hour.loc[mask] = num.loc[mask]


    # 0000 / 0100 / 2300
    mask_hhmm = (
        num.notna()
        & (num >= 100)
        & (num <= 2359)
    )

    hour.loc[mask_hhmm] = (
        num.loc[mask_hhmm] // 100
    )


    # 00:00 / 13:00
    colon = s.str.extract(
        r"^(\d{1,2}):",
        expand=False
    )

    hour = hour.fillna(
        pd.to_numeric(
            colon,
            errors="coerce"
        )
    )


    # 0시 / 13시
    kor = s.str.extract(
        r"(\d{1,2})\s*시",
        expand=False
    )

    hour = hour.fillna(
        pd.to_numeric(
            kor,
            errors="coerce"
        )
    )


    return hour



def detect_encoding(path):

    for enc in [
        "utf-8-sig",
        "utf-8",
        "cp949",
        "euc-kr"
    ]:

        try:

            pd.read_csv(
                path,
                encoding=enc,
                nrows=5
            )

            return enc

        except:
            pass


    raise ValueError(
        "CSV encoding을 찾지 못했습니다."
    )



def action_label(x):

    if pd.isna(x):
        return "MISSING_DATA"

    if x >= 1:
        return "ADD"

    if x <= -1:
        return "REMOVE"

    return "KEEP"



